-- ── integrity rules (CHECK constraints, ported from the PostgreSQL migrations) ──
ALTER TABLE `JournalEntry` ADD CONSTRAINT `JournalEntry_amounts_nonnegative` CHECK (`debit` >= 0 AND `credit` >= 0);
ALTER TABLE `JournalEntry` ADD CONSTRAINT `JournalEntry_single_side` CHECK ((`debit` > 0) <> (`credit` > 0));
ALTER TABLE `Voucher` ADD CONSTRAINT `Voucher_amounts_nonnegative` CHECK (`amount` >= 0 AND `paidAmount` >= 0 AND `subtotal` >= 0 AND `discount` >= 0 AND `vatAmount` >= 0);
ALTER TABLE `VoucherPayment` ADD CONSTRAINT `VoucherPayment_amount_positive` CHECK (`amount` > 0);
ALTER TABLE `VoucherItem` ADD CONSTRAINT `VoucherItem_quantity_positive` CHECK (`quantity` > 0 AND `baseQuantity` > 0);
ALTER TABLE `VoucherItem` ADD CONSTRAINT `VoucherItem_amounts_nonnegative` CHECK (`rate` >= 0 AND `discount` >= 0 AND `amount` >= 0);
ALTER TABLE `StockMovement` ADD CONSTRAINT `StockMovement_quantities_nonnegative` CHECK (`quantityIn` >= 0 AND `quantityOut` >= 0);
ALTER TABLE `StockMovement` ADD CONSTRAINT `StockMovement_single_direction` CHECK ((`quantityIn` > 0) <> (`quantityOut` > 0));
ALTER TABLE `Customer` ADD CONSTRAINT `Customer_credit_terms_nonnegative` CHECK (`creditLimit` >= 0 AND `creditDays` >= 0);
ALTER TABLE `Supplier` ADD CONSTRAINT `Supplier_credit_days_nonnegative` CHECK (`creditDays` >= 0);
ALTER TABLE `Unit` ADD CONSTRAINT `Unit_factor_positive` CHECK (`factor` > 0);
ALTER TABLE `ProductBatch` ADD CONSTRAINT `ProductBatch_quantity_nonneg` CHECK (`quantity` >= 0);
ALTER TABLE `ProductBatch` ADD CONSTRAINT `ProductBatch_prices_nonneg` CHECK (`purchasePrice` >= 0 AND `salePrice` >= 0);
ALTER TABLE `ProductBatch` ADD CONSTRAINT `ProductBatch_mfg_before_expiry` CHECK (`mfgDate` IS NULL OR `expiryDate` IS NULL OR `mfgDate` <= `expiryDate`);
ALTER TABLE `ProductBatch` ADD CONSTRAINT `ProductBatch_batchNo_not_blank` CHECK (CHAR_LENGTH(TRIM(`batchNo`)) > 0);
ALTER TABLE `Notification` ADD CONSTRAINT `Notification_level_nonneg` CHECK (`level` IS NULL OR `level` >= 0);
ALTER TABLE `Business` ADD CONSTRAINT `Business_expiry_warning_days_valid` CHECK (JSON_LENGTH(`expiryWarningDays`) BETWEEN 1 AND 8);
ALTER TABLE `AuthThrottle` ADD CONSTRAINT `AuthThrottle_attempts_nonneg` CHECK (`attempts` >= 0);
ALTER TABLE `Session` ADD CONSTRAINT `Session_expiry_after_creation` CHECK (`expiresAt` > `createdAt`);
ALTER TABLE `User` ADD CONSTRAINT `User_has_identifier` CHECK (`email` IS NOT NULL OR `mobile` IS NOT NULL);
ALTER TABLE `User` ADD CONSTRAINT `User_mobile_format` CHECK (`mobile` IS NULL OR `mobile` REGEXP '^01[3-9][0-9]{8}$');
ALTER TABLE `User` ADD CONSTRAINT `User_email_lowercase` CHECK (`email` IS NULL OR CAST(`email` AS BINARY) = CAST(LOWER(`email`) AS BINARY));
ALTER TABLE `SmsMessage` ADD CONSTRAINT `SmsMessage_parts_positive` CHECK (`parts` >= 1);
ALTER TABLE `SmsMessage` ADD CONSTRAINT `SmsMessage_attempts_valid` CHECK (`attempts` >= 0 AND `maxAttempts` >= 1);
ALTER TABLE `SmsMessage` ADD CONSTRAINT `SmsMessage_recipient_format` CHECK (`recipient` REGEXP '^01[3-9][0-9]{8}$');
ALTER TABLE `SmsMessage` ADD CONSTRAINT `SmsMessage_encoding_valid` CHECK (`encoding` IN ('GSM7', 'UCS2'));
ALTER TABLE `SmsOtp` ADD CONSTRAINT `SmsOtp_attempts_valid` CHECK (`attempts` >= 0 AND `maxAttempts` >= 1);
ALTER TABLE `SmsSettings` ADD CONSTRAINT `SmsSettings_threshold_nonneg` CHECK (`lowBalanceThreshold` >= 0 AND `dueReminderEveryDays` >= 1);

