INSERT IGNORE INTO `Feature` (`key`, `nameBn`, `nameEn`, `descriptionBn`, `descriptionEn`, `icon`, `tier`, `status`, `defaultEnabled`, `sortOrder`, `updatedAt`) VALUES ('ADVANCED_REPORTING', 'অ্যাডভান্সড রিপোর্টিং', 'Advanced Reporting', 'দৈনিক সারসংক্ষেপ, নগদ প্রবাহ, আয়-ব্যয়, স্টক মূল্যায়ন, বিক্রয়-ক্রয় বিশ্লেষণ ও আদায় রিপোর্ট। মূল হিসাবের রিপোর্ট (লেজার, ট্রায়াল ব্যালেন্স, লাভ-ক্ষতি, ব্যালান্স শীট) সবসময় চালু।', 'Daily summary, cash flow, income & expense, stock valuation, sales/purchase analysis and collection reports. Core books (ledger, trial balance, P&L, balance sheet) stay on.', '📊', 'PAID', 'AVAILABLE', 1, 80, CURRENT_TIMESTAMP(3));
